from taf.internal.managedobject import ManagedObject
from taf.ue.plugin.mtk.injecter import Injecter


class MaceProxy(ManagedObject, Injecter):
    def __init__(self, **kwargs):
        super(MaceProxy, self).__init__()
        self._raw = kwargs['raw']
        self._port = kwargs['port']
        self._edb_file_path = kwargs['edb_file_path']
        self._inject_methods_from(self._raw)

    def _teardown(self):
        self._raw.disconnect_device()

    def _setup(self):
        self._raw.connect_device(com=self._port, edb_file_path=self._edb_file_path)
